def solve_v2(input_grid):
    b0_row0 = input_grid[0]
    h = len(input_grid)

    def has_band(band_start, band_end, c):
        return any(input_grid[r][c] != 0 for r in range(band_start, band_end+1))

    def get_band_value(band_start, band_end, c):
        for r in range(band_start, band_end+1):
            if input_grid[r][c] != 0:
                return input_grid[r][c]
        return None

    result = []

    # Process each of the 3 output rows
    for out_row in range(3):
        if out_row == 0:
            src_band = (6, 8)  # Band 2
        elif out_row == 1:
            src_band = (3, 5)  # Band 1
        else:
            src_band = (0, 2)  # Band 0

        res_row = []
